// USGS 3DEP DEM, baked from pois/eagles-nest-kt22/dem-tight.tif.
// THE MERGE'S THIRD ELEVATION FRAME. red-dog/dem-tight (1400 m @ 1.367 m/px)
// stops 710 m west of the origin; the whole KT-22 sector, its summit and the
// Eagle's Nest massif sit outside it and would otherwise carve against the
// 3.125 m/px dem-wide surround. This is the KT bundle's own 3DEP export,
// 1600 m @ 1.5625 m/px, covering the KT-22 Express line base to summit.
// Carried at FULL NATIVE 1024^2 — no decimation; the only loss is the Int16
// decimetre quantisation (+/-0.05 m).
// Row 0 = SOUTH edge, +x east. Values are DECIMETRES relative to z0 = 1890.0 m.
// Same world frame and same transform as dem-data.mjs: ENU ground metres about
// 39.19197,-120.23108, x = (merc_x - merc_x0)*cos(lat0).
//
// SEAM: where this frame and red-dog/dem-tight overlap, the two independent
// 3DEP exports agree to 0.014 m (mean |dz| over 40,000 random points) — see
// work/bake_dem_kt.py, printed at bake time and quoted in REPORT.md.
// 1600 m frame, ASL 1889.9..2460.8//
// CROPPED by poi-lab tools/export-red-dog (specs/0001 D13/D41):
//   DEM_KT 1024 -> 256 (4x, 2048 KB -> 128 KB raw)
// Block-mean decimation. span / ox / oy are untouched, so every frame still
// registers 1:1 with the DEM stack; only the sample spacing changed.

export const DEM_KT = { span: 1600.0, n: 256, ox: -720.41, oy: -312.80, b64: "" };
export default DEM_KT;
